test $(netstat -tunap | grep ':9000' >/dev/null; echo $?); do killall netcat || true;
# Assuming the use of iptables for IP blocking, replace 192.168.56.10 with a variable if desired
echo "Dropping incoming traffic from suspicious IP to prevent further attempts" | sudo tee -a /var/log/iptables_ruleset >/dev/null-n;
sudo iptables -I INPUT 7 -s 192.168.56.10 -j DROP;
